-- enrich existing exhibitors (new columns; fill-blank for owner/website/phone)
update public.exhibitors e set
  sales_status = l.sales_status, priority_tier = l.priority_tier,
  priority_tier_label = l.priority_tier_label,
  ttm_loads = l.ttm_loads, ttm_margin = l.ttm_margin, last_pickup = l.last_pickup,
  legacy_loads = l.legacy_loads, legacy_first_year = l.legacy_first_year,
  legacy_last_year = l.legacy_last_year, legacy_billed = l.legacy_billed,
  legacy_margin = l.legacy_margin, legacy_margin_per_load = l.legacy_margin_per_load,
  shows_shipped = l.shows_shipped, shows_confirmed_2026 = l.shows_confirmed_2026,
  top_show_cities = l.top_show_cities,
  owner_rep = coalesce(nullif(e.owner_rep,''), l.owner_rep),
  website = coalesce(nullif(e.website,''), l.website),
  primary_contact_phone = coalesce(nullif(e.primary_contact_phone,''), l.phone),
  imported_at = now()
from _legacy_import l
where lower(e.company_name) = lower(l.company_name);

-- insert companies with no existing match
insert into public.exhibitors (company_name, owner_rep, website, primary_contact_phone,
  source, sales_status, priority_tier, priority_tier_label, ttm_loads, ttm_margin, last_pickup,
  legacy_loads, legacy_first_year, legacy_last_year, legacy_billed, legacy_margin,
  legacy_margin_per_load, shows_shipped, shows_confirmed_2026, top_show_cities, imported_at)
select l.company_name, l.owner_rep, l.website, l.phone, 'legacy_import',
  l.sales_status, l.priority_tier, l.priority_tier_label, l.ttm_loads, l.ttm_margin, l.last_pickup,
  l.legacy_loads, l.legacy_first_year, l.legacy_last_year, l.legacy_billed, l.legacy_margin,
  l.legacy_margin_per_load, l.shows_shipped, l.shows_confirmed_2026, l.top_show_cities, now()
from _legacy_import l
where not exists (select 1 from public.exhibitors e where lower(e.company_name) = lower(l.company_name));

-- per-show history (idempotent upsert)
insert into public.exhibitor_show_history (exhibitor_id, show_name, show_loads, first_year, last_year, billed, margin, confirmed_2026)
select distinct on (e.id, h.show_name) e.id, h.show_name, h.show_loads, h.first_year, h.last_year, h.billed, h.margin, h.confirmed_2026
from _legacy_history h
join public.exhibitors e on lower(e.company_name) = lower(h.company_name)
order by e.id, h.show_name
on conflict (exhibitor_id, show_name) do update set
  show_loads = excluded.show_loads, first_year = excluded.first_year, last_year = excluded.last_year,
  billed = excluded.billed, margin = excluded.margin, confirmed_2026 = excluded.confirmed_2026;
drop table if exists _legacy_import; drop table if exists _legacy_history;
commit;
